<script setup lang="ts">
import {ref,onMounted,computed} from 'vue';
import type {Point} from './model.ts';
export interface Place {id:string;name:string;point:Point;confidence:string;url:string;review?:boolean}
const emit=defineEmits<{close:[];visit:[place:Place]}>(),query=ref(''),places=ref<Place[]>([]),error=ref('');
onMounted(async()=>{try{const r=await fetch('/places9.json');if(!r.ok)throw Error('Location sources unavailable');places.value=(await r.json()).places;}catch(e){error.value=String(e);}});
const filtered=computed(()=>places.value.filter((p,i,a)=>p.name.toLowerCase().includes(query.value.toLowerCase())&&a.findIndex(x=>x.name===p.name)===i));
</script>
<template><section class="locations-panel" aria-label="Wukari locations"><header><h2>Find a place</h2><button aria-label="Close locations" @click="emit('close')">×</button></header><input v-model="query" aria-label="Search source-backed locations" placeholder="Search Wukari or Federal University…"/><p>Names from OSM and cited university research. Source-backed does not mean field verified or publicly accessible.</p><p v-if="error" role="alert">{{ error }}</p><article v-for="p in filtered" :key="p.id"><h3>{{ p.name }}</h3><small>{{ p.confidence }}</small><div><button @click="emit('visit',p)">{{ p.review?'Review location':'View on map' }}</button><a :href="p.url" target="_blank" rel="noreferrer">Source ↗</a></div></article><p>FUW has no verified gate, boundary or access route here. Its review remains separate and non-spawning. Anonymous shops, finishes, street furniture and traffic are illustrative; they are not named real businesses or live traffic.</p></section></template>
<style scoped>.locations-panel{position:absolute;z-index:8;inset:16px 16px 45px auto;width:min(430px,calc(100% - 32px));overflow:auto;background:#faf8ed;border:1px solid #bbcab4;border-radius:18px;padding:22px;box-shadow:0 8px 35px #243f3733}.locations-panel header{display:flex;justify-content:space-between;align-items:center}.locations-panel p,.locations-panel small{font-size:11px;line-height:1.6;color:#526957}.locations-panel input{width:100%;padding:14px;border:1px solid #b2c3a9;border-radius:8px;font:inherit;font-size:12px}.locations-panel article{border-bottom:1px solid #d1dbc9;padding:12px 0}.locations-panel h3{font-size:14px}.locations-panel button{min-height:44px;padding:10px;border:1px solid #b2c3a9;border-radius:8px;background:#e2eadb}.locations-panel article div{display:flex;align-items:center;gap:18px;margin-top:10px;font-size:11px}</style>
